{"code":"import random

def generate(rng):
    # Sparse black canvas with colored endpoint pairs, each pair defining a 45-degree diagonal.
    h = rng.randint(5, 18)
    w = rng.randint(5, 18)
    grid = [[0 for _ in range(w)] for _ in range(h)]
    palette = [2, 3, 9]
    n = rng.randint(1, min(4, len(palette)))
    colors = rng.sample(palette, n)
    used = set()
    for col in colors:
        choices = []
        # endpoints are diagonal, with at least one intervening cell, as in the example
        for r in range(h):
            for c in range(w):
                for dr, dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                    length = rng.randint(2, max(2, min(h,w)//2 + 1))
                    r2, c2 = r + dr*length, c + dc*length
                    if 0 <= r2 < h and 0 <= c2 < w:
                        if (r,c) not in used and (r2,c2) not in used:
                            choices.append((r,c,r2,c2))
        if not choices: continue
        r,c,r2,c2 = rng.choice(choices)
        grid[r][c] = col; grid[r2][c2] = col
        used.update([(r,c),(r2,c2)])
    return grid"}

